const (
        blobSeed uint32 = 0xA5F0C3E1
        blobCRC  uint32 = 0x7CA59846
)

// decoy material
var decoyKeys = []string{
        "fork",
        "admin",
        "X9m#Kp2$Lv7@Qn4?",
        "N1ghtF0x_MCP!",
        "CORRECT-LICENSE",
}

func xorshiftDecrypt(data []byte, seed uint32) []byte {
        s := seed
        out := make([]byte, len(data))
        for i, b := range data {
                s ^= s << 13
                s ^= s >> 17
                s ^= s << 5
                out[i] = b ^ byte((s>>8)&0xff) ^ byte(i&0xff)
        }
        return out
}

func crc32ieee(data []byte) uint32 {
        var table [256]uint32
        for i := 0; i < 256; i++ {
                c := uint32(i)
                for j := 0; j < 8; j++ {
                        if c&1 != 0 {
                                c = 0xEDB88320 ^ (c >> 1)
                        } else {
                                c >>= 1
                        }
                }
                table[i] = c
        }
        crc := uint32(0xFFFFFFFF)
        for _, b := range data {
                crc = table[byte(crc)^b] ^ (crc >> 8)
        }
        return crc ^ 0xFFFFFFFF
}

func unlockBytecode() ([]byte, bool) {
        seed := poisonSeed(blobSeed)
        raw := xorshiftDecrypt(encBlob, seed)
        if crc32ieee(raw) != blobCRC {
                // second-chance decoy path: still wrong
                _ = decoyKeys
                return nil, false
        }
        return raw, true
}

func checkLicense(input string) bool {
        // reject obvious decoys early with same failure mode
        for _, d := range decoyKeys {
                if input == d {
                        // fall through to real path anyway (same timing-ish)
                        break
                }
        }
        code, ok := unlockBytecode()
        if !ok {
                return false
        }
        // stage A: junk opaque gate
        if !opaqueGate(len(input)) {
                return false
        }
        return runVM(code, []byte(input))
}

func opaqueGate(n int) bool {
        x := uint32(n) ^ 0xA5A5A5A5
        y := x*0x01000193 + 0x9E3779B9
        // always true for normal sizes, but dense math
        return ((y ^ (y >> 16)) | 1) != 0
}
